export function projectErrorHandlingDetail(
  root: ReturnType<typeof errorLabAri>,
  contentMap: ContentMap<ContentRegistry>,
  args: {
    params: ErrorHandlingDetailParams;
    executionContext: ErrorHandlingDetailExecutionContext;
    failures: ReadonlyMap<ResourceKey, ResolutionError>;
  }
): ErrorHandlingDetailResult {
  const memo = new Map<string, unknown>();
  const failures = args.failures;

  const projectOnErrorLab = (
    resource: ReturnType<typeof errorLabAri>,
    payload: ErrorLabPayload
  ): ErrorHandlingDetail_ErrorLab => {
    const shell: any = { __typename: "ErrorLab" };
    memo.set(resource.toString(), shell);
    shell.softSingle = projectEdge(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.softSingleId,
        locale: resource.key[0].locale,
      }),
      "setNull"
    );
    shell.errorSingle = projectEdge(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.errorSingleId,
        locale: resource.key[0].locale,
      }),
      "setError"
    );
    shell.throwSingle = projectNode(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.throwSingleId,
        locale: resource.key[0].locale,
      })
    );
    shell.softItems = payload.softItems.map((softLink) =>
      projectEdge(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: softLink.id,
          locale: resource.key[0].locale,
        }),
        "setNull"
      )
    );
    shell.errorItems = payload.errorItems.map((errorLink) =>
      projectEdge(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: errorLink.id,
          locale: resource.key[0].locale,
        }),
        "setError"
      )
    );
    shell.throwItems = payload.throwItems.map((throwLink) =>
      projectNode(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: throwLink.id,
          locale: resource.key[0].locale,
        })
      )
    );
    return shell;
  };

  const projectOnEntry = (
    resource: ReturnType<typeof entryAri>,
    payload: EntryPayload
  ): ErrorHandlingDetail_Entry => {
    if (payload.kind == "Hero") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.image = projectEdge(
        assetAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.imageId,
          locale: resource.key[0].locale,
        }),
        "setNull"
      );
      return shell;
    } else if (payload.kind == "Page") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      return shell;
    } else {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      return shell;
    }
  };

  const projectOnAsset = (
    resource: ReturnType<typeof assetAri>,
    payload: AssetPayload
  ): ErrorHandlingDetail_Asset => {
    const shell: any = { __typename: "Asset" };
    memo.set(resource.toString(), shell);
    shell.kind = payload.kind;
    shell.id = payload.id;
    shell.url = payload.url;
    shell.title = payload.title;
    shell.asset_type = payload.asset_type;
    return shell;
  };

  const projectNode = (ari: ApplicationResourceIdentifier): unknown => {
    const key = ari.toString();
    if (memo.has(key)) return memo.get(key);
    const loadedPayload = contentMap.get(ari as never);
    if (loadedPayload === undefined) return undefined;
    switch (ari.type) {
      case "ErrorLab":
        return projectOnErrorLab(
          ari as ReturnType<typeof errorLabAri>,
          loadedPayload as ErrorLabPayload
        );
      case "Entry":
        return projectOnEntry(ari as ReturnType<typeof entryAri>, loadedPayload as EntryPayload);
      case "Asset":
        return projectOnAsset(ari as ReturnType<typeof assetAri>, loadedPayload as AssetPayload);
      default:
        throw new Error(
          "projectErrorHandlingDetail: unexpected resource type " + JSON.stringify(ari.type)
        );
    }
  };

  const projectEdge = (
    ari: ApplicationResourceIdentifier,
    onFailure: "setNull" | "setError"
  ): unknown => {
    const value = projectNode(ari);
    if (value !== undefined) return value;
    if (onFailure === "setNull") return null;
    const failure = failures.get(ari.toString());
    if (failure === undefined) {
      throw new Error(
        "projectErrorHandlingDetail: missing collected failure for " + ari.toString()
      );
    }
    return toResolutionErrorData(failure);
  };

  return projectNode(root) as ErrorHandlingDetailResult;
}

export function projectPageDetail(
  root: ReturnType<typeof pageAri>,
  contentMap: ContentMap<ContentRegistry>,
  args: {
    params: PageDetailParams;
    executionContext: PageDetailExecutionContext;
    redirects: ReadonlyMap<ResourceKey, ApplicationResourceIdentifier>;
    failures: ReadonlyMap<ResourceKey, ResolutionError>;
  }
): PageDetailResult {
  const memo = new Map<string, unknown>();
  const failures = args.failures;

  const projectOnPage = (
    resource: ReturnType<typeof pageAri>,
    payload: PagePayload
  ): PageDetail_Page => {
    const shell: any = { __typename: "Page" };
    memo.set(resource.toString(), shell);
    shell.id = payload.id;
    shell.title = payload.title;
    shell.menu = projectEdge(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.menuId,
        locale: resource.key[0].locale,
      }),
      "setNull"
    );
    shell.footer = projectEdge(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.footerId,
        locale: resource.key[0].locale,
      }),
      "setNull"
    );
    shell.strips = payload.strips.map((pageLink) =>
      projectEdge(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: pageLink.id,
          locale: resource.key[0].locale,
        }),
        "setNull"
      )
    );
    shell.related = payload.related.map((ref) =>
      projectEdge(customReferenceAri({ ref: ref, locale: resource.key[0].locale }), "setNull")
    );
    return shell;
  };

  const projectOnEntry = (
    resource: ReturnType<typeof entryAri>,
    payload: EntryPayload
  ): PageDetail_Entry => {
    if (payload.kind == "Hero") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.image = projectEdge(
        assetAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.imageId,
          locale: resource.key[0].locale,
        }),
        "setNull"
      );
      return shell;
    } else if (payload.kind == "Tabs") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.tabs = payload.tabs.map((tabLink) =>
        projectEdge(
          entryAri({
            spaceId: resource.key[0].spaceId,
            environmentId: resource.key[0].environmentId,
            id: tabLink.id,
            locale: resource.key[0].locale,
          }),
          "setNull"
        )
      );
      return shell;
    } else if (payload.kind == "Tab") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.strips = payload.strips.map((entryLink) =>
        projectEdge(
          entryAri({
            spaceId: resource.key[0].spaceId,
            environmentId: resource.key[0].environmentId,
            id: entryLink.id,
            locale: resource.key[0].locale,
          }),
          "setNull"
        )
      );
      return shell;
    } else if (payload.kind == "Menu" || payload.kind == "Footer") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.logo = projectEdge(
        assetAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.logoId,
          locale: resource.key[0].locale,
        }),
        "setNull"
      );
      return shell;
    } else if (payload.kind == "Product") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.sku = payload.sku;
      shell.title = payload.title;
      return shell;
    } else if (payload.kind == "Page") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      return shell;
    } else if (payload.kind == "SiteInternalLink") {
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.target = projectEdge(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.targetId,
          locale: resource.key[0].locale,
        }),
        "setNull"
      );
      return shell;
    } else {
      const defaultPayload = payload as EntryPayload;
      const shell: any = { __typename: "Entry" };
      memo.set(resource.toString(), shell);
      shell.kind = defaultPayload.kind;
      shell.id = defaultPayload.id;
      return shell;
    }
  };

  const projectOnAsset = (
    resource: ReturnType<typeof assetAri>,
    payload: AssetPayload
  ): PageDetail_Asset => {
    const shell: any = { __typename: "Asset" };
    memo.set(resource.toString(), shell);
    shell.kind = payload.kind;
    shell.id = payload.id;
    shell.url = payload.url;
    shell.title = payload.title;
    shell.asset_type = payload.asset_type;
    return shell;
  };

  const projectNode = (ari: ApplicationResourceIdentifier): unknown => {
    const key = ari.toString();
    if (memo.has(key)) return memo.get(key);
    const loadedPayload = contentMap.get(ari as never);
    if (loadedPayload === undefined) return undefined;
    switch (ari.type) {
      case "Page":
        return projectOnPage(ari as ReturnType<typeof pageAri>, loadedPayload as PagePayload);
      case "Entry":
        return projectOnEntry(ari as ReturnType<typeof entryAri>, loadedPayload as EntryPayload);
      case "Asset":
        return projectOnAsset(ari as ReturnType<typeof assetAri>, loadedPayload as AssetPayload);
      case "CustomReference": {
        const canonical = args.redirects.get(ari.toString());
        if (canonical === undefined) return undefined;
        return projectNode(canonical);
      }
      default:
        throw new Error("projectPageDetail: unexpected resource type " + JSON.stringify(ari.type));
    }
  };

  const projectEdge = (
    ari: ApplicationResourceIdentifier,
    onFailure: "setNull" | "setError"
  ): unknown => {
    const value = projectNode(ari);
    if (value !== undefined) return value;
    if (onFailure === "setNull") return null;
    const failure = failures.get(ari.toString());
    if (failure === undefined) {
      throw new Error("projectPageDetail: missing collected failure for " + ari.toString());
    }
    return toResolutionErrorData(failure);
  };

  return projectNode(root) as PageDetailResult;
}

export function projectProductDetail(
  root: ReturnType<typeof catalogProductAri>,
  contentMap: ContentMap<ContentRegistry>,
  args: {
    params: ProductDetailParams;
    executionContext: ProductDetailExecutionContext;
    failures: ReadonlyMap<ResourceKey, ResolutionError>;
  }
): ProductDetailResult {
  const memo = new Map<string, unknown>();
  const failures = args.failures;

  const projectOnCatalogProduct = (
    resource: ReturnType<typeof catalogProductAri>,
    payload: CatalogProductPayload
  ): ProductDetail_CatalogProduct => {
    const shell: any = { __typename: "CatalogProduct" };
    memo.set(resource.toString(), shell);
    shell.id = payload.id;
    shell.title = payload.title;
    shell.price = projectEdge(
      offerPriceAri({ id: payload.priceId, market: resource.key[0].market }),
      "setNull"
    );
    shell.stock = projectEdge(
      stockLevelAri({ sku: payload.sku, warehouse: "eu-central" }),
      "setNull"
    );
    shell.media = projectEdge(productMediaAri({ id: payload.mediaId }), "setNull");
    return shell;
  };

  const projectOnOfferPrice = (
    resource: ReturnType<typeof offerPriceAri>,
    payload: OfferPricePayload
  ): ProductDetail_OfferPrice => {
    const shell: any = { __typename: "OfferPrice" };
    memo.set(resource.toString(), shell);
    shell.id = payload.id;
    shell.amountCents = payload.amountCents;
    shell.currency = payload.currency;
    return shell;
  };

  const projectOnStockLevel = (
    resource: ReturnType<typeof stockLevelAri>,
    payload: StockLevelPayload
  ): ProductDetail_StockLevel => {
    const shell: any = { __typename: "StockLevel" };
    memo.set(resource.toString(), shell);
    shell.sku = payload.sku;
    shell.available = payload.available;
    return shell;
  };

  const projectOnProductMedia = (
    resource: ReturnType<typeof productMediaAri>,
    payload: ProductMediaPayload
  ): ProductDetail_ProductMedia => {
    const shell: any = { __typename: "ProductMedia" };
    memo.set(resource.toString(), shell);
    shell.id = payload.id;
    shell.url = payload.url;
    shell.alt = payload.alt;
    return shell;
  };

  const projectNode = (ari: ApplicationResourceIdentifier): unknown => {
    const key = ari.toString();
    if (memo.has(key)) return memo.get(key);
    const loadedPayload = contentMap.get(ari as never);
    if (loadedPayload === undefined) return undefined;
    switch (ari.type) {
      case "CatalogProduct":
        return projectOnCatalogProduct(
          ari as ReturnType<typeof catalogProductAri>,
          loadedPayload as CatalogProductPayload
        );
      case "OfferPrice":
        return projectOnOfferPrice(
          ari as ReturnType<typeof offerPriceAri>,
          loadedPayload as OfferPricePayload
        );
      case "StockLevel":
        return projectOnStockLevel(
          ari as ReturnType<typeof stockLevelAri>,
          loadedPayload as StockLevelPayload
        );
      case "ProductMedia":
        return projectOnProductMedia(
          ari as ReturnType<typeof productMediaAri>,
          loadedPayload as ProductMediaPayload
        );
      default:
        throw new Error(
          "projectProductDetail: unexpected resource type " + JSON.stringify(ari.type)
        );
    }
  };

  const projectEdge = (
    ari: ApplicationResourceIdentifier,
    onFailure: "setNull" | "setError"
  ): unknown => {
    const value = projectNode(ari);
    if (value !== undefined) return value;
    if (onFailure === "setNull") return null;
    const failure = failures.get(ari.toString());
    if (failure === undefined) {
      throw new Error("projectProductDetail: missing collected failure for " + ari.toString());
    }
    return toResolutionErrorData(failure);
  };

  return projectNode(root) as ProductDetailResult;
}

export type ResolveErrorHandlingDetailInput = {
  params: ErrorHandlingDetailParams;
  sources: readonly DataSource<ContentRegistry, ErrorHandlingDetailExecutionContext>[];
  schedulingMode?: SchedulingMode;
  budget?: ResolutionBudgetOptions;
  observer?: ResolutionObserver;
  executionContext: ErrorHandlingDetailExecutionContext;
  backingResources?: ReadonlyMap<ResourceKey, unknown>;
  signal?: AbortSignal;
};

export type ResolveErrorHandlingDetailResult = {
  errorHandlingDetail: ErrorHandlingDetailResult;
  contentMap: ContentMap<ContentRegistry>;
  islands: IslandMap;
  islandDependencies: IslandDependencyMap;
  errors: readonly ResolutionError[];
  promotedResourceKeys: readonly ResourceKey[];
};

export async function resolveErrorHandlingDetail(
  input: ResolveErrorHandlingDetailInput
): Promise<ResolveErrorHandlingDetailResult> {
  const root = errorLabAri({
    spaceId: input.executionContext.spaceId,
    environmentId: input.executionContext.environmentId,
    id: input.params.labId,
    locale: input.executionContext.locale,
  });
  const resolver = createResourceGraphResolver<
    ContentRegistry,
    ErrorHandlingDetailExecutionContext
  >({
    sources: input.sources,
    strategy: createErrorHandlingDetailStrategy(input.params).build(),
    schedulingMode: input.schedulingMode,
    budget: input.budget,
    observer: input.observer,
  });

  const { contentMap, islands, islandDependencies, errors, failures, promotedResourceKeys } =
    await resolver.resolve({
      roots: [root],
      executionContext: input.executionContext,
      backingResources: input.backingResources,
      signal: input.signal,
    });

  const errorHandlingDetail = projectErrorHandlingDetail(root, contentMap, {
    params: input.params,
    executionContext: input.executionContext,
    failures,
  });

  return {
    errorHandlingDetail,
    contentMap,
    islands,
    islandDependencies,
    errors,
    promotedResourceKeys,
  };
}

